<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import {
  BarChart3,
  CalendarDays,
  CalendarPlus,
  ChevronLeft,
  ChevronRight,
  Clock3,
  FileText,
  PauseCircle,
  Pencil,
  PlayCircle,
  RefreshCw,
  Send,
  Settings2,
  Trash2,
  TrendingUp,
} from 'lucide-vue-next'
import { openAgendaOperator } from './tenantNavigation'
import { confirmDialog } from './appDialog'

type Period='day'|'week'|'month'|'quarter'|'semester'|'year'
type Tab='overview'|'calendar'|'reports'|'automation'
type Appointment={id:string;starts_at:string;ends_at:string;status:string;customer_name:string;customer_phone?:string|null;service_name?:string|null;professional_name:string;price?:number|null}
type Report={
  period:Period;anchor:string;range:{starts_at:string;ends_at:string};
  synthetic:{appointments:number;unique_customers:number;completed:number;cancelled:number;no_show:number;estimated_revenue:number;completion_rate:number;no_show_rate:number};
  analytical:{curve:Array<{date:string;appointments:number}>;statuses:Array<{status:string;count:number}>;services:Array<{name:string;count:number}>;professionals:Array<{name:string;count:number}>}
}
type ReportSchedule={enabled:boolean;period:Period;delivery_channels:Array<'email'|'whatsapp'>;email:string;whatsapp:string;format:'link'|'pdf'|'link_pdf';hour:number}
type Envelope<T>={data?:T;error?:{message?:string}}

const visible=ref(window.location.hash==='#agenda')
const tab=ref<Tab>('overview')
const loading=ref(false)
const saving=ref(false)
const error=ref('')
const message=ref('')
const appointments=ref<Appointment[]>([])
const tenantTimezone=ref('America/Bahia')
const report=ref<Report|null>(null)
const overviewWeek=ref<Report|null>(null)
const overviewMonth=ref<Report|null>(null)
const period=ref<Period>('month')
const anchor=ref(todayKey())
const monthCursor=ref(startOfMonth(new Date()))
const selectedDay=ref(todayKey())
const schedules=ref<ReportSchedule[]>([])
const scheduleForm=ref<ReportSchedule>({enabled:false,period:'month',delivery_channels:['email'],email:localStorage.getItem('scheduler_pro_email')||'',whatsapp:'',format:'link',hour:8})

const statusLabels:Record<string,string>={PENDING:'Pendente',AWAITING_CONFIRMATION:'Aguardando confirmação',CONFIRMED:'Confirmado',CHECKED_IN:'Check-in',IN_PROGRESS:'Em atendimento',COMPLETED:'Concluído',CANCELLED:'Cancelado',RESCHEDULED:'Reagendado',NO_SHOW:'Não compareceu'}
const periodLabels:Record<Period,string>={day:'Diário',week:'Semanal',month:'Mensal',quarter:'Trimestral',semester:'Semestral',year:'Anual'}

const monthTitle=computed(()=>monthCursor.value.toLocaleDateString('pt-BR',{month:'long',year:'numeric'}))
const selectedAppointments=computed(()=>appointments.value.filter((item)=>dayKey(item.starts_at)===selectedDay.value).sort((a,b)=>+new Date(a.starts_at)-+new Date(b.starts_at)))
const todayAppointments=computed(()=>appointments.value.filter((item)=>dayKey(item.starts_at)===todayKey()))
const monthDays=computed(()=>{
  const first=startOfMonth(monthCursor.value)
  const gridStart=new Date(first);gridStart.setDate(first.getDate()-first.getDay())
  return Array.from({length:42},(_,index)=>{
    const date=new Date(gridStart);date.setDate(gridStart.getDate()+index)
    const key=localDateKey(date)
    return{date,key,current:date.getMonth()===monthCursor.value.getMonth(),today:key===todayKey(),count:appointments.value.filter((item)=>dayKey(item.starts_at)===key).length}
  })
})
const maxCurve=computed(()=>Math.max(1,...(report.value?.analytical.curve.map((item)=>item.appointments)||[1])))

function token():string{return localStorage.getItem('scheduler_pro_access_token')||''}
function localDateKey(value:Date):string{const parts=new Intl.DateTimeFormat('en-CA',{timeZone:tenantTimezone.value,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(value);const val=(type:string)=>parts.find(item=>item.type===type)?.value||'';return `${val('year')}-${val('month')}-${val('day')}`}
function todayKey():string{return localDateKey(new Date())}
function dayKey(value:string):string{return localDateKey(new Date(value))}
function startOfMonth(value:Date):Date{return new Date(value.getFullYear(),value.getMonth(),1,12)}
function money(value:number):string{return new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(value||0))}
function time(value:string):string{return new Intl.DateTimeFormat('pt-BR',{timeZone:tenantTimezone.value,hour:'2-digit',minute:'2-digit'}).format(new Date(value))}
function status(value:string):string{return statusLabels[value]||value}
function periodLabel(value:Period):string{return periodLabels[value]}
function flash(value:string):void{message.value=value;window.setTimeout(()=>{if(message.value===value)message.value=''},3500)}
function copySchedule(item:ReportSchedule):ReportSchedule{return{...item,email:item.email||'',whatsapp:item.whatsapp||'',delivery_channels:[...(item.delivery_channels||[])]}}

async function api<T>(path:string,init:RequestInit={}):Promise<T>{
  const response=await fetch(`/api/v1${path}`,{...init,cache:'no-store',headers:{Accept:'application/json',...(init.body?{'content-type':'application/json'}:{}),Authorization:`Bearer ${token()}`,...(init.headers||{})}})
  const payload=await response.json().catch(()=>({})) as Envelope<T>
  if(!response.ok)throw new Error(payload.error?.message||`Falha HTTP ${response.status}`)
  return payload.data as T
}
async function fetchReport(target:Period,targetAnchor=anchor.value):Promise<Report>{return api<Report>(`/agenda/reports/summary?period=${target}&anchor=${encodeURIComponent(targetAnchor)}`)}
async function loadTenantContext():Promise<void>{const settings=await api<{timezone?:string}>('/settings/tenant').catch(()=>({timezone:tenantTimezone.value}));if(settings?.timezone)tenantTimezone.value=settings.timezone}
function calendarRange():{startsAt:string;endsAt:string}{const first=startOfMonth(monthCursor.value);const gridStart=new Date(first);gridStart.setDate(first.getDate()-first.getDay());const gridEnd=new Date(gridStart);gridEnd.setDate(gridStart.getDate()+42);const key=(d:Date)=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;return{startsAt:`${key(gridStart)}T00:00:00`,endsAt:`${key(gridEnd)}T00:00:00`}}
async function loadBase():Promise<void>{const range=calendarRange();appointments.value=await api<Appointment[]>(`/appointments?starts_at=${encodeURIComponent(range.startsAt)}&ends_at=${encodeURIComponent(range.endsAt)}`)}
async function loadOverview():Promise<void>{const [week,month]=await Promise.all([fetchReport('week',todayKey()),fetchReport('month',todayKey())]);overviewWeek.value=week;overviewMonth.value=month}
async function loadReport():Promise<void>{report.value=await fetchReport(period.value)}
async function loadSchedules():Promise<void>{schedules.value=await api<ReportSchedule[]>('/agenda/reports/schedules')}
async function load():Promise<void>{if(!visible.value)return;loading.value=true;error.value='';try{await loadTenantContext();await Promise.all([loadBase(),loadOverview(),loadReport(),loadSchedules()])}catch(exc){error.value=exc instanceof Error?exc.message:'Não foi possível carregar a Agenda.'}finally{loading.value=false}}
function setTab(value:Tab):void{tab.value=value;if(value==='reports')void loadReport();if(value==='automation')void loadSchedules()}
function shiftMonth(delta:number):void{monthCursor.value=new Date(monthCursor.value.getFullYear(),monthCursor.value.getMonth()+delta,1,12);void loadBase()}
function chooseDay(key:string):void{selectedDay.value=key;const d=new Date(`${key}T12:00:00`);const next=startOfMonth(d);const changed=next.getMonth()!==monthCursor.value.getMonth()||next.getFullYear()!==monthCursor.value.getFullYear();monthCursor.value=next;if(changed)void loadBase()}
function openNew(startsAt?:string):void{openAgendaOperator({tab:'quick',startsAt})}
function openManage():void{openAgendaOperator({tab:'manage'})}
function openRecurring():void{openAgendaOperator({tab:'recurring'})}
function toggleChannel(channel:'email'|'whatsapp'):void{const channels=scheduleForm.value.delivery_channels;const index=channels.indexOf(channel);if(index>=0)channels.splice(index,1);else channels.push(channel)}
async function persistSchedules(next:ReportSchedule[],notice:string):Promise<void>{
  saving.value=true;error.value=''
  try{const persisted=await api<ReportSchedule[]>('/agenda/reports/schedules',{method:'PUT',body:JSON.stringify({schedules:next})});schedules.value=persisted.map(copySchedule);flash(notice)}
  catch(exc){error.value=exc instanceof Error?exc.message:'Falha ao atualizar a automação.';throw exc}
  finally{saving.value=false}
}
async function saveSchedule():Promise<void>{const existing=schedules.value.filter((item)=>item.period!==scheduleForm.value.period);const next=[...existing,copySchedule(scheduleForm.value)];try{await persistSchedules(next,'Automação do relatório salva.')}catch{/* mensagem já tratada */}}
function editSchedule(item:ReportSchedule):void{scheduleForm.value=copySchedule(item);flash(`${periodLabel(item.period)} carregado para edição.`)}
async function toggleSchedule(item:ReportSchedule):Promise<void>{const next=schedules.value.map(row=>row.period===item.period?{...copySchedule(row),enabled:!row.enabled}:copySchedule(row));try{await persistSchedules(next,item.enabled?'Automação pausada.':'Automação ativada.')}catch{/* mensagem já tratada */}}
async function deleteSchedule(item:ReportSchedule):Promise<void>{if(!await confirmDialog({title:'Excluir automação',message:`Excluir a automação ${periodLabel(item.period).toLowerCase()}?`,danger:true,confirmLabel:'Excluir'}))return;const next=schedules.value.filter(row=>row.period!==item.period).map(copySchedule);try{await persistSchedules(next,'Automação excluída.');if(scheduleForm.value.period===item.period)scheduleForm.value={enabled:false,period:'month',delivery_channels:['email'],email:localStorage.getItem('scheduler_pro_email')||'',whatsapp:'',format:'link',hour:8}}catch{/* mensagem já tratada */}}
function syncVisibility():void{visible.value=window.location.hash==='#agenda';document.body.classList.toggle('sp-agenda-center-open',visible.value);if(visible.value)void load()}
function onAppointmentsChanged():void{if(visible.value)void loadBase()}
onMounted(()=>{window.addEventListener('hashchange',syncVisibility);window.addEventListener('scheduler-pro-appointments-changed',onAppointmentsChanged);syncVisibility()})
onUnmounted(()=>{window.removeEventListener('hashchange',syncVisibility);window.removeEventListener('scheduler-pro-appointments-changed',onAppointmentsChanged);document.body.classList.remove('sp-agenda-center-open')})
</script>

<template>
  <Teleport v-if="visible" to=".tenant-console .main-content">
    <section class="sp-agenda-center">
      <header class="sp-agenda-center-head">
        <div><span>Agenda gerencial</span><h1>Agenda</h1><p>Operação, calendário e visão analítica em uma única área. Use o Operador da Agenda para criar atendimentos de qualquer lugar.</p></div>
        <div class="sp-agenda-head-actions"><button @click="openRecurring"><Clock3 :size="16"/>Recorrência</button><button @click="openManage"><Settings2 :size="16"/>Operar</button><button class="primary" @click="openNew()"><CalendarPlus :size="16"/>Novo</button></div>
      </header>
      <p v-if="message" class="sp-agenda-success">{{message}}</p><p v-if="error" class="sp-agenda-error">{{error}}</p>
      <nav class="sp-agenda-tabs"><button :class="{active:tab==='overview'}" @click="setTab('overview')"><TrendingUp :size="16"/>Visão gerencial</button><button :class="{active:tab==='calendar'}" @click="setTab('calendar')"><CalendarDays :size="16"/>Calendário</button><button :class="{active:tab==='reports'}" @click="setTab('reports')"><BarChart3 :size="16"/>Relatórios</button><button :class="{active:tab==='automation'}" @click="setTab('automation')"><Send :size="16"/>Automação</button></nav>
      <div v-if="loading" class="sp-agenda-loading"><RefreshCw class="spin" :size="22"/>Atualizando a agenda...</div>

      <template v-else-if="tab==='overview'">
        <div class="sp-agenda-metrics"><article><span>Hoje</span><strong>{{todayAppointments.length}}</strong><small>atendimento(s)</small></article><article><span>Esta semana</span><strong>{{overviewWeek?.synthetic.appointments||0}}</strong><small>{{overviewWeek?.synthetic.unique_customers||0}} cliente(s)</small></article><article><span>Este mês</span><strong>{{overviewMonth?.synthetic.appointments||0}}</strong><small>{{overviewMonth?.synthetic.completed||0}} concluído(s)</small></article><article><span>Receita estimada</span><strong>{{money(overviewMonth?.synthetic.estimated_revenue||0)}}</strong><small>mês atual</small></article><article><span>Conclusão</span><strong>{{overviewMonth?.synthetic.completion_rate||0}}%</strong><small>dos atendimentos válidos</small></article><article><span>Não compareceu</span><strong>{{overviewMonth?.synthetic.no_show_rate||0}}%</strong><small>taxa mensal</small></article></div>
        <div class="sp-agenda-overview-grid"><article class="sp-agenda-card"><header><div><span>Hoje</span><h2>Atendimentos do dia</h2></div><button @click="openNew()"><CalendarPlus :size="15"/>Novo</button></header><div class="sp-day-list"><button v-for="item in todayAppointments.slice(0,12)" :key="item.id" @click="openManage"><time>{{time(item.starts_at)}}</time><div><strong>{{item.customer_name}}</strong><small>{{item.service_name||'Sem serviço'}} · {{item.professional_name}}</small></div><em>{{status(item.status)}}</em></button><div v-if="!todayAppointments.length" class="sp-empty"><CalendarDays :size="34"/><strong>Nenhum atendimento hoje.</strong><span>O botão Novo abre o mesmo Operador global.</span></div></div></article><article class="sp-agenda-card"><header><div><span>Resumo mensal</span><h2>Distribuição por serviço</h2></div><button @click="setTab('reports')"><FileText :size="15"/>Detalhar</button></header><div class="sp-ranking"><div v-for="item in overviewMonth?.analytical.services.slice(0,8)||[]" :key="item.name"><span>{{item.name}}</span><strong>{{item.count}}</strong></div><div v-if="!overviewMonth?.analytical.services.length" class="sp-empty compact">Sem dados neste mês.</div></div></article></div>
      </template>

      <template v-else-if="tab==='calendar'">
        <div class="sp-calendar-layout"><article class="sp-agenda-card sp-calendar-card"><div class="sp-calendar-head"><button @click="shiftMonth(-1)"><ChevronLeft :size="18"/></button><strong>{{monthTitle}}</strong><button @click="shiftMonth(1)"><ChevronRight :size="18"/></button></div><div class="sp-weekdays"><span v-for="day in ['Dom','Seg','Ter','Qua','Qui','Sex','Sáb']" :key="day">{{day}}</span></div><div class="sp-calendar-grid"><button v-for="cell in monthDays" :key="cell.key" :class="{outside:!cell.current,today:cell.today,selected:selectedDay===cell.key,occupied:cell.count}" @click="chooseDay(cell.key)"><span>{{cell.date.getDate()}}</span><small v-if="cell.count">{{cell.count}}</small><i v-if="cell.count"></i></button></div></article><article class="sp-agenda-card sp-selected-day"><header><div><span>Dia selecionado</span><h2>{{new Date(selectedDay+'T12:00:00').toLocaleDateString('pt-BR',{dateStyle:'full'})}}</h2></div><button @click="openNew(selectedDay+'T08:00')"><CalendarPlus :size="15"/>Novo</button></header><div class="sp-day-list"><button v-for="item in selectedAppointments" :key="item.id" @click="openManage"><time>{{time(item.starts_at)}}</time><div><strong>{{item.customer_name}}</strong><small>{{item.service_name||'Sem serviço'}} · {{item.professional_name}}</small></div><em>{{status(item.status)}}</em></button><div v-if="!selectedAppointments.length" class="sp-empty"><CalendarDays :size="38"/><strong>Nenhum atendimento neste dia.</strong><span>Escolha outra data ou crie um novo atendimento.</span></div></div></article></div>
      </template>

      <template v-else-if="tab==='reports'">
        <div class="sp-report-toolbar"><label>Período<select v-model="period" @change="loadReport"><option v-for="value in (['day','week','month','quarter','semester','year'] as Period[])" :key="value" :value="value">{{periodLabel(value)}}</option></select></label><label>Data de referência<input v-model="anchor" type="date" @change="loadReport"/></label><button @click="loadReport"><RefreshCw :size="16"/>Atualizar</button></div>
        <div v-if="report" class="sp-report-content"><div class="sp-agenda-metrics report"><article><span>Agendamentos</span><strong>{{report.synthetic.appointments}}</strong></article><article><span>Clientes únicos</span><strong>{{report.synthetic.unique_customers}}</strong></article><article><span>Concluídos</span><strong>{{report.synthetic.completed}}</strong></article><article><span>Cancelados</span><strong>{{report.synthetic.cancelled}}</strong></article><article><span>Faltas</span><strong>{{report.synthetic.no_show}}</strong></article><article><span>Receita estimada</span><strong>{{money(report.synthetic.estimated_revenue)}}</strong></article></div><div class="sp-report-grid"><article class="sp-agenda-card"><header><div><span>Visão analítica</span><h2>Curva de atendimentos</h2></div></header><div class="sp-curve"><div v-for="item in report.analytical.curve" :key="item.date"><span>{{new Date(item.date+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'})}}</span><i><b :style="{width:`${Math.max(3,item.appointments*100/maxCurve)}%`}"></b></i><strong>{{item.appointments}}</strong></div><div v-if="!report.analytical.curve.length" class="sp-empty compact">Sem dados no período.</div></div></article><article class="sp-agenda-card"><header><div><span>Visão sintética</span><h2>Indicadores</h2></div></header><div class="sp-ranking"><div><span>Taxa de conclusão</span><strong>{{report.synthetic.completion_rate}}%</strong></div><div><span>Taxa de não comparecimento</span><strong>{{report.synthetic.no_show_rate}}%</strong></div><div v-for="item in report.analytical.statuses" :key="item.status"><span>{{status(item.status)}}</span><strong>{{item.count}}</strong></div></div></article><article class="sp-agenda-card"><header><div><span>Serviços</span><h2>Atendimentos por serviço</h2></div></header><div class="sp-ranking"><div v-for="item in report.analytical.services" :key="item.name"><span>{{item.name}}</span><strong>{{item.count}}</strong></div></div></article><article class="sp-agenda-card"><header><div><span>Responsáveis</span><h2>Atendimentos por profissional</h2></div></header><div class="sp-ranking"><div v-for="item in report.analytical.professionals" :key="item.name"><span>{{item.name}}</span><strong>{{item.count}}</strong></div></div></article></div></div>
      </template>

      <template v-else>
        <div class="sp-automation-grid">
          <article class="sp-agenda-card"><header><div><span>Relatórios automáticos</span><h2>Programar envio</h2></div></header><p class="sp-card-copy">Defina o período, o canal e o formato. O destinatário pode receber por e-mail, pelo próprio WhatsApp ou pelos dois canais.</p><div class="sp-automation-form"><label>Período<select v-model="scheduleForm.period"><option v-for="value in (['day','week','month','quarter','semester','year'] as Period[])" :key="value" :value="value">{{periodLabel(value)}}</option></select></label><label>Horário<input v-model.number="scheduleForm.hour" type="number" min="0" max="23"/></label><label>Formato<select v-model="scheduleForm.format"><option value="link">Link online</option><option value="pdf">PDF</option><option value="link_pdf">Link + PDF</option></select></label><label class="sp-toggle"><input v-model="scheduleForm.enabled" type="checkbox"/>Automação ativa</label><div class="sp-channel-picks"><button :class="{active:scheduleForm.delivery_channels.includes('email')}" @click="toggleChannel('email')">E-mail</button><button :class="{active:scheduleForm.delivery_channels.includes('whatsapp')}" @click="toggleChannel('whatsapp')">WhatsApp</button></div><label v-if="scheduleForm.delivery_channels.includes('email')">E-mail<input v-model="scheduleForm.email" type="email"/></label><label v-if="scheduleForm.delivery_channels.includes('whatsapp')">WhatsApp<input v-model="scheduleForm.whatsapp" inputmode="tel"/></label><button class="sp-save-schedule" :disabled="saving" @click="saveSchedule"><Send :size="16"/>{{saving?'Salvando...':'Salvar automação'}}</button></div></article>
          <article class="sp-agenda-card"><header><div><span>Configurações salvas</span><h2>Rotinas configuradas</h2></div></header><div class="sp-schedules"><article v-for="item in schedules" :key="item.period" class="sp-schedule-item"><button class="sp-schedule-main" type="button" @click="editSchedule(item)"><div><strong>{{periodLabel(item.period)}}</strong><small>{{item.enabled?'Ativa':'Pausada'}} · {{item.format==='pdf'?'PDF':item.format==='link_pdf'?'Link + PDF':'Link online'}}</small><small>{{item.delivery_channels.join(' + ')||'Sem canal'}}</small></div><em>{{String(item.hour).padStart(2,'0')}}:00</em></button><div class="sp-schedule-actions"><button type="button" title="Editar automação" @click="editSchedule(item)"><Pencil :size="14"/><span>Editar</span></button><button type="button" :title="item.enabled?'Pausar automação':'Ativar automação'" @click="toggleSchedule(item)"><PauseCircle v-if="item.enabled" :size="14"/><PlayCircle v-else :size="14"/><span>{{item.enabled?'Pausar':'Ativar'}}</span></button><button type="button" class="danger" title="Excluir automação" @click="deleteSchedule(item)"><Trash2 :size="14"/><span>Excluir</span></button></div></article><div v-if="!schedules.length" class="sp-empty"><Send :size="34"/><strong>Nenhuma automação configurada.</strong><span>Configure a primeira rotina ao lado.</span></div></div></article>
        </div>
      </template>
    </section>
  </Teleport>
</template>

<style>
body.sp-agenda-center-open .tenant-console .main-content>.page-header,body.sp-agenda-center-open .tenant-console .main-content>.success-banner,body.sp-agenda-center-open .tenant-console .main-content>.error-banner,body.sp-agenda-center-open .tenant-console .main-content>.view-stack,body.sp-agenda-center-open .tenant-console .main-content>.sp-agenda-smart-root{display:none!important}.sp-agenda-center{padding:2px 0 86px;color:#10213b}.sp-agenda-center-head{display:flex;justify-content:space-between;gap:24px;align-items:flex-end;margin-bottom:16px}.sp-agenda-center-head>div:first-child{max-width:760px}.sp-agenda-center-head span,.sp-agenda-card header span{color:#2563eb;font-size:10px;font-weight:900;letter-spacing:.11em;text-transform:uppercase}.sp-agenda-center-head h1{margin:5px 0 6px;font-size:34px;letter-spacing:-.04em}.sp-agenda-center-head p,.sp-card-copy{margin:0;color:#52647c;font-size:13px;line-height:1.6}.sp-agenda-head-actions{display:flex;gap:8px;flex-wrap:wrap}.sp-agenda-head-actions button,.sp-report-toolbar button{min-height:42px;border:1px solid #d9e3ef;border-radius:11px;background:#fff;color:#203650;padding:0 13px;display:flex;align-items:center;gap:6px;font:inherit;font-size:11px;font-weight:850;cursor:pointer}.sp-agenda-head-actions button.primary{border-color:#2563eb;background:#2563eb;color:#fff}.sp-agenda-tabs{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;margin-bottom:14px;padding:6px;border:1px solid #dce5ef;border-radius:15px;background:#fff}.sp-agenda-tabs button{min-height:43px;border:0;border-radius:10px;background:transparent;color:#556a83;display:flex;align-items:center;justify-content:center;gap:7px;font:inherit;font-size:11px;font-weight:850;cursor:pointer}.sp-agenda-tabs button.active{background:#eaf2ff;color:#1d4ed8}.sp-agenda-loading{min-height:320px;display:flex;align-items:center;justify-content:center;gap:9px;color:#53657d}.sp-agenda-success,.sp-agenda-error{padding:10px 13px;border-radius:11px;font-size:12px